import type { ComponentPropsWithoutRef, ReactNode } from "react";

type Variant = "primary" | "danger" | "ghost";

// Accept every native <button> prop, and add our own.
type ButtonProps = ComponentPropsWithoutRef<"button"> & {
  variant?: Variant;
  icon?: ReactNode;
};

export function Button({ variant = "primary", type = "button", icon, children, ...rest }: ButtonProps) {
  return (
    <button type={type} className={`btn btn-${variant}`} {...rest}>
      {icon}
      {children}
    </button>
  );
}

type ActionProps =
  | { as: "link"; href: string; external?: boolean; label: string }
  | { as: "button"; onClick: () => void; disabled?: boolean; label: string };

function Action(props: ActionProps) {
  if (props.as === "link") {
    return props.external
      ? <a href={props.href} target="_blank" rel="noopener noreferrer">{props.label}</a>
      : <a href={props.href}>{props.label}</a>;
  }
  return <button type="button" onClick={props.onClick} disabled={props.disabled}>{props.label}</button>;
}
